using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Services;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class EmploymentTimelineTests
{
 class Time:TimeProvider{public DateTimeOffset Now=new(2026,11,24,10,0,0,TimeSpan.Zero);public override DateTimeOffset GetUtcNow()=>Now;}
 class User(bool pay=true):ICurrentUser{public string Email=>"schedule@example.local";public int? EmployeeId=>1;public int UserId=>1;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>true;public bool Can(string p)=>pay || p!=Perm.EmpPay;}
 static async Task<AppDbContext> Db(){var d=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.MigrateAsync();await SeedData.InitializeAsync(d,"Admin123!","Demo123!",new DateTime(2026,11,24));return d;}
 static EmploymentTimeline S(AppDbContext d,Time t,bool pay=true){var u=new User(pay);var c=new AppClock(t);return new(d,u,c,new AuditService(d,u,c));}
 static EmploymentChange C(Employee e)=>new(){EmployeeId=e.Id,EffectiveOn=new(2026,12,1),DepartmentId=e.DepartmentId==1?2:1,BranchId=e.BranchId,JobTitleId=e.JobTitleId,ShiftId=e.ShiftId,ManagerId=e.ManagerId,BasicSalary=e.BasicSalary+500,Reason="Future transfer"};
 [Fact]public async Task FutureAssignmentLeavesCurrentStateAndAppliesOnceAtBoundary(){await using var d=await Db();var t=new Time();var s=S(d,t);var e=(await d.Set<Employee>().FindAsync(6))!;var old=e.DepartmentId;var change=C(e);await s.ScheduleAsync(change);await s.ApplyDueAsync();Assert.Equal(old,e.DepartmentId);Assert.Null(change.AppliedAt);t.Now=new(2026,12,1,10,0,0,TimeSpan.Zero);await s.ApplyDueAsync();Assert.Equal(change.DepartmentId,e.DepartmentId);Assert.NotNull(change.AppliedAt);Assert.Single(await d.Set<EmployeeAssignment>().Where(x=>x.EmployeeId==6 && x.EffectiveFrom==change.EffectiveOn).ToListAsync());await s.ApplyDueAsync();Assert.Single(await d.Set<EmployeeAssignment>().Where(x=>x.EmployeeId==6 && x.EffectiveFrom==change.EffectiveOn).ToListAsync());}
 [Fact]public async Task CancelledScheduleNeverApplies(){await using var d=await Db();var t=new Time();var s=S(d,t);var e=(await d.Set<Employee>().FindAsync(6))!;var old=e.DepartmentId;var change=C(e);await s.ScheduleAsync(change);await s.CancelAsync(change.Id,"Plan withdrawn");t.Now=new(2026,12,2,10,0,0,TimeSpan.Zero);await s.ApplyDueAsync();Assert.Equal(old,e.DepartmentId);Assert.Null(change.AppliedAt);}
 [Fact]public async Task NoPayPermissionCannotScheduleSalaryIncrease(){await using var d=await Db();var t=new Time();var e=(await d.Set<Employee>().FindAsync(6))!;var change=C(e);await S(d,t,false).ScheduleAsync(change);Assert.Equal(e.BasicSalary,change.BasicSalary);}
 [Fact]public async Task StatusTransitionIsEffectiveDated(){await using var d=await Db();var t=new Time();var s=S(d,t);var e=(await d.Set<Employee>().FindAsync(6))!;var change=new EmploymentChange{EmployeeId=6,Kind="Status",Status=EmployeeStatus.Suspended,EffectiveOn=new(2026,12,1),Reason="Status change test"};await s.ScheduleAsync(change);Assert.Equal(EmployeeStatus.Active,e.Status);t.Now=new(2026,12,1,10,0,0,TimeSpan.Zero);await s.ApplyDueAsync();Assert.Equal(EmployeeStatus.Suspended,e.Status);Assert.True(await d.Set<StatusHistory>().AnyAsync(x=>x.EmployeeId==6 && x.At==change.EffectiveOn && x.To==EmployeeStatus.Suspended));}
 [Fact]public async Task PastScheduleAndDuplicatePendingScheduleAreRejected(){await using var d=await Db();var t=new Time();var s=S(d,t);var e=(await d.Set<Employee>().FindAsync(6))!;var bad=C(e);bad.EffectiveOn=new(2026,11,23);await Assert.ThrowsAsync<DomainException>(()=>s.ScheduleAsync(bad));await s.ScheduleAsync(C(e));await Assert.ThrowsAsync<DomainException>(()=>s.ScheduleAsync(C(e)));}
}
